const t={cockpit:()=>[{target:()=>null,title:"The Cockpit & Canvas",icon:"fad fa-rocket-launch",color:"#62c9ff",content:"Welcome to your Cockpit. The 3D canvas is your viewport into the Youniverse. You can interact with it by dragging the mouse. <br><br> To change your navigation paradigm, open the <strong>Nucleos</strong> spark and navigate to the Behavior tab."},{target:".u-zoom-slider",title:"The Hyperdrive",icon:"fad fa-rocket-launch",color:"#62c9ff",content:"This is your cockpit's hyperdrive scrollbar. Use it to fly forward and backward through the space around you at whatever speed you like.",placement:"left"}],navigation:()=>[{target:".v-navigation-drawer--left",title:"The User Rail",icon:"fal fa-compass",color:"#62c9ff",content:"This sidebar is your primary navigation menu. It intelligently expands when you hover over it to give you more space on your screen.",placement:"right"},{target:".pin-toggle-btn",title:"Pinning the Rail",icon:"fal fa-compass",color:"#62c9ff",content:"If you prefer to keep the menu open all the time, click this pin to lock it in place.",placement:"right"},{target:".v-navigation-drawer--left .v-list:nth-of-type(2)",title:"Your Sparks",icon:"fal fa-compass",color:"#62c9ff",content:"These are your Sparks, the sub-apps and tools that run your Youniverse. You can pin your favorites here.",placement:"right"}],launchpad:e=>[{target:".launch-btn",title:"The Launchpad",icon:"fal fa-rocket-launch",color:"#62c9ff",content:"This button opens the Launchpad. It contains the complete library of all your installed Sparks.",placement:"right"},{target:()=>null,title:"Window Management",icon:"fal fa-rocket-launch",color:"#62c9ff",content:"When you launch a Spark, it opens in a free-floating Window. You can drag, resize, maximize, or minimize them, just like a traditional operating system.",onEnter:()=>{e.launchApp("app-launcher")}},{target:".u-system-bar",title:"Screensaver Mode",icon:"fal fa-rocket-launch",color:"#62c9ff",content:"You can enter Screensaver mode from the bottom system bar to hide the UI and just enjoy the 3D canvas.",placement:"top"}],"custom-panels":()=>[{target:".topbar-zone--left",title:"The Left Zone",icon:"fal fa-sliders-h",color:"#62c9ff",content:"Drag and drop chips here to align them to the left side of the window chrome.",placement:"top"},{target:".topbar-zone--center",title:"The Center Zone",icon:"fal fa-sliders-h",color:"#62c9ff",content:"Chips placed here will be perfectly centered. This is a great spot for the Window Title.",placement:"top"},{target:".topbar-zone--right",title:"The Right Zone",icon:"fal fa-sliders-h",color:"#62c9ff",content:"Drop chips here to align them to the right. Typically used for Close, Maximize, and Minimize actions.",placement:"top"},{target:".preset-icons-container",title:"Customization Complete",icon:"fal fa-sliders-h",color:"#62c9ff",content:"Once you're happy with your layout, it's saved automatically! Click the preset icons below at any time to return to a standard OS layout.",placement:"top"}]};export{t as systemTours};
